task automatic t_irq_level_latched_status();
  apb_write(GPIOEN, 32'h0000_0001);
  apb_write(INTTYPE0, 32'h1);
  apb_write(INTEN, 32'h1);
  gpio_in[0] = 1'b1;
  idle(4);
  check(irq === 1'b1, "interrupt output high after rising edge");
  idle(4);
  check(irq === 1'b1, "interrupt output remains high as a level before INTSTATUS read");
  apb_read(INTSTATUS, rd);
  idle(1);
  check(irq === 1'b0, "interrupt output low after INTSTATUS read clears latched status");
endtask

