test_code:
task automatic t_inttype_level_high();
  // Enable GPIO0
  apb_write(GPIOEN, 32'h0000_0001);
  // Configure INTTYPE0 for pin0 as level‑high (11)
  apb_write(INTTYPE0, 32'h3);
  // Enable interrupt for GPIO0
  apb_write(INTEN, 32'h0000_0001);
  // Drive pin high
  gpio_in[0] = 1'b1;
  idle(6);
  // Read INTSTATUS
  apb_read(INTSTATUS, rd);
  check_eq(rd, 1, "INTTYPE=11 level interrupt: INTSTATUS[0] set while GPIO0 is high");
  // Drive pin low
  gpio_in[0] = 1'b0;
  idle(6);
  // Read INTSTATUS again
  apb_read(INTSTATUS, rd);
  // check removed after test review: not required by the spec
  // Cleanup: disable interrupt and clear status
  apb_write(INTEN, 32'h0);
  apb_read(INTSTATUS, rd); // read‑clear
  gpio_in[0] = 1'b0;
endtask
